import sys
from collections import deque

def read_input():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    edges = [(int(data[2 + 2 * i]) - 1, int(data[3 + 2 * i]) - 1) for i in range(m)]
    return n, m, edges

def merge_operations_to_caterpillar(n, m, edges):
    if n == 1:
        return 0

    adj = [[] for _ in range(n)]
    degree = [0] * n

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1

    leaves = deque([i for i in range(n) if degree[i] == 1])
    removed = set()

    while leaves:
        leaf = leaves.popleft()
        if leaf in removed:
            continue
        removed.add(leaf)
        for neighbor in adj[leaf]:
            if neighbor in removed:
                continue
            degree[neighbor] -= 1
            if degree[neighbor] == 1:
                leaves.append(neighbor)

    components = 0
    visited = set()

    def bfs(start):
        q = deque([start])
        while q:
            node = q.popleft()
            if node in visited:
                continue
            visited.add(node)
            for neighbor in adj[node]:
                if neighbor not in visited and degree[neighbor] > 1:
                    q.append(neighbor)

    for i in range(n):
        if degree[i] > 1 and i not in visited:
            bfs(i)
            components += 1

    return max(0, n - components - 1)

def main():
    n, m, edges = read_input()
    result = merge_operations_to_caterpillar(n, m, edges)
    print(result)

if __name__ == "__main__":
    main()
